from html import escape

from fastapi.responses import HTMLResponse

from .schemas import BotCatalogItem


def _page(title: str, body: str) -> HTMLResponse:
    return HTMLResponse(f"""<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)}</title><style>
    :root {{ color-scheme:dark; --bg:#0b1020; --panel:#121a2d; --panel2:#19233b; --border:#2b395d; --text:#eef3ff; --muted:#9fb0d4; --green:#41d392; --red:#ff6b81; --yellow:#f6c667; }}
    * {{ box-sizing:border-box; }} body {{ margin:0; font-family:Inter,Arial,sans-serif; color:var(--text); background:linear-gradient(180deg,#0b1020,#11192c); }} main {{ max-width:1240px; margin:auto; padding:36px 20px 48px; }} h1,h2,p {{ margin-top:0; }} .muted {{ color:var(--muted); }} .header {{ display:flex; align-items:flex-start; justify-content:space-between; gap:16px; margin-bottom:28px; }} button {{ font:inherit; cursor:pointer; }} .link-button {{ color:var(--muted); background:transparent; border:0; padding:0; }} .panel,.card {{ background:rgba(18,26,45,.92); border:1px solid var(--border); border-radius:10px; }}
    @media(max-width:640px) {{ main {{ padding:24px 16px; }} .header {{ flex-direction:column; }} }}
    </style></head><body>{body}</body></html>""")


def render_login_page(error: str | None = None, status_code: int = 200) -> HTMLResponse:
    error_html = f'<p class="error">{escape(error)}</p>' if error else ""
    response = _page("2Lotus | Resultados de bots", f"""<main class="login"><section class="panel"><p class="muted">2LOTUS</p><h1>Resultados dos bots</h1><p class="muted">Acesse os testes e indicadores de performance.</p>{error_html}<form method="post" action="/login"><label>Senha<input type="password" name="password" autocomplete="current-password" required autofocus></label><button type="submit">Entrar</button></form></section></main><style>
    .login {{ min-height:100vh; display:grid; place-items:center; padding:20px; }} .login .panel {{ width:min(100%,400px); padding:30px; }} .login label {{ display:grid; gap:8px; margin:24px 0 14px; font-size:14px; }} .login input {{ border:1px solid var(--border); border-radius:8px; background:#0d1527; color:var(--text); padding:12px; font:inherit; }} .login button {{ width:100%; border:0; border-radius:8px; background:var(--green); color:#052315; padding:12px; font-weight:700; }} .error {{ color:var(--red); font-size:14px; }}
    </style>""")
    response.status_code = status_code
    return response


def render_catalog_page(bots: list[BotCatalogItem]) -> HTMLResponse:
    cards = "".join(
        f'''<a class="bot card" href="/bots/{escape(bot.id)}"><p class="muted">{escape(bot.symbol)} · {escape(bot.timeframe)}</p><h2>{escape(bot.name)}</h2><p class="muted">{escape(bot.description)}</p><strong>Ver resultados →</strong></a>'''
        for bot in bots
    ) or '<p class="muted">Nenhum bot foi cadastrado.</p>'
    return _page("2Lotus | Bots de teste", f"""<main><header class="header"><div><p class="muted">2LOTUS</p><h1>Resultados dos bots</h1><p class="muted">Selecione um teste para visualizar seu desempenho.</p></div><form method="post" action="/logout"><button class="link-button" type="submit">Sair</button></form></header><section class="grid">{cards}</section></main><style>
    .grid {{ display:grid; grid-template-columns:repeat(auto-fit,minmax(260px,1fr)); gap:16px; }} .bot {{ min-height:220px; display:flex; flex-direction:column; align-items:flex-start; padding:22px; color:var(--text); text-decoration:none; }} .bot h2,.bot p {{ margin-bottom:12px; }} .bot strong {{ color:var(--green); margin-top:auto; }}
    </style>""")


def render_results_page(bot: BotCatalogItem) -> HTMLResponse:
    bot_id = escape(bot.id)
    return _page(f"{bot.name} | Resultados", f"""<main><header class="header"><div><p class="muted">{escape(bot.symbol)} · {escape(bot.timeframe)} · {escape(bot.strategy_profile)}</p><h1>{escape(bot.name)}</h1><p class="muted">{escape(bot.description)}</p></div><div class="actions"><a href="/bots">Todos os bots</a><form method="post" action="/logout"><button class="link-button" type="submit">Sair</button></form><p class="muted" id="latest-trade">Carregando...</p></div></header>
    <section class="cards"><article class="card"><p class="muted">PnL líquido</p><strong id="net-pnl">-</strong><span id="gross-pnl"></span></article><article class="card"><p class="muted">Trades fechados</p><strong id="trades-count">-</strong><span id="open-positions"></span></article><article class="card"><p class="muted">Win rate</p><strong id="win-rate">-</strong><span id="wl-breakdown"></span></article><article class="card"><p class="muted">Profit factor</p><strong id="profit-factor">-</strong><span id="avg-rr"></span></article><article class="card"><p class="muted">Melhor / pior</p><strong id="best-trade">-</strong><span id="worst-trade"></span></article></section>
    <section class="layout"><article class="panel"><h2>PnL diário</h2><div id="daily-pnl"></div></article><article class="panel"><h2>Trades recentes</h2><div id="recent-trades"></div></article></section></main><style>
    .actions {{ display:flex; align-items:flex-start; justify-content:flex-end; flex-wrap:wrap; gap:12px; text-align:right; }} .actions a {{ color:var(--muted); }} .actions p {{ width:100%; margin:0; }} .cards {{ display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); gap:12px; margin-bottom:20px; }} .card,.panel {{ padding:18px; }} .card strong {{ display:block; font-size:27px; margin-bottom:9px; }} .card span {{ color:var(--muted); font-size:13px; }} .layout {{ display:grid; grid-template-columns:1.2fr .8fr; gap:16px; }} .daily-row,.trade-row {{ display:grid; gap:12px; padding:12px 0; border-top:1px solid rgba(159,176,212,.14); }} .daily-row {{ grid-template-columns:1fr auto; }} .trade-row {{ grid-template-columns:70px 70px 1fr auto; }} .bar {{ height:8px; border-radius:999px; background:#0d1527; overflow:hidden; }} .bar span {{ display:block; height:100%; background:linear-gradient(90deg,#4f8cff,var(--green)); }} .green {{ color:var(--green); }} .red {{ color:var(--red); }} .yellow {{ color:var(--yellow); }} @media(max-width:1080px) {{ .cards {{ grid-template-columns:repeat(2,minmax(0,1fr)); }} .layout {{ grid-template-columns:1fr; }} }} @media(max-width:640px) {{ .cards {{ grid-template-columns:1fr; }} .trade-row {{ grid-template-columns:1fr; gap:5px; }} }}
    </style><script>
    const money = value => new Intl.NumberFormat('pt-BR', {{style:'currency',currency:'USD'}}).format(value || 0); const date = value => value ? new Date(value).toLocaleString('pt-BR', {{timeZone:'UTC'}}) + ' UTC' : '-'; const color = value => value > 0 ? 'green' : value < 0 ? 'red' : 'yellow';
    async function load() {{ const response = await fetch('/api/bots/{bot_id}/results'); if (!response.ok) throw new Error('Não foi possível carregar os resultados.'); const data = await response.json(); const s = data.summary; document.getElementById('latest-trade').textContent = data.latest_trade_at_utc ? 'Último trade registrado em ' + date(data.latest_trade_at_utc) : 'Sem operações registradas'; document.getElementById('net-pnl').textContent = money(s.net_pnl); document.getElementById('net-pnl').className = color(s.net_pnl); document.getElementById('gross-pnl').textContent = 'Lucro ' + money(s.gross_profit) + ' | Perda ' + money(s.gross_loss); document.getElementById('trades-count').textContent = s.trades_count; document.getElementById('open-positions').textContent = s.open_positions + ' posições em aberto'; document.getElementById('win-rate').textContent = s.win_rate_pct.toFixed(2) + '%'; document.getElementById('wl-breakdown').textContent = s.wins + ' wins | ' + s.losses + ' losses'; document.getElementById('profit-factor').textContent = s.profit_factor.toFixed(2); document.getElementById('avg-rr').textContent = 'RR médio ' + s.avg_rr.toFixed(2); document.getElementById('best-trade').textContent = money(s.best_trade); document.getElementById('best-trade').className = color(s.best_trade); document.getElementById('worst-trade').textContent = 'Pior ' + money(s.worst_trade); const daily = document.getElementById('daily-pnl'); daily.innerHTML = data.daily_pnl.length ? data.daily_pnl.slice(-12).reverse().map(p => `<div class="daily-row"><span>${{new Date(p.day + 'T00:00:00Z').toLocaleDateString('pt-BR')}}</span><span class="${{color(p.net_pnl)}}">${{money(p.net_pnl)}}</span><div class="bar"><span style="width:${{Math.max(Math.abs(p.net_pnl), 4)}}%"></span></div></div>`).join('') : '<p class="muted">Ainda não há trades fechados.</p>'; const trades = document.getElementById('recent-trades'); trades.innerHTML = data.recent_trades.length ? data.recent_trades.map(t => `<div class="trade-row"><strong>${{t.side.toUpperCase()}}</strong><span class="muted">${{t.symbol}}<br>${{t.timeframe}}</span><span>${{t.setup}}<br><small class="muted">${{date(t.closed_at_utc || t.opened_at_utc)}}</small></span><strong class="${{color(t.net_pnl)}}">${{money(t.net_pnl)}}</strong></div>`).join('') : '<p class="muted">Sem histórico recente.</p>'; }} load().catch(error => document.getElementById('latest-trade').textContent = error.message);
    </script>""")
